SET ROLE ice_p0_02_owner;
CREATE FUNCTION catalog.new_item_scope_allowed(s uuid,cap text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT catalog.is_admin() AND EXISTS(SELECT 1 FROM catalog.source_scope_grant g WHERE g.scope_id=s AND g.profile_id=nullif(current_setting('request.jwt.claim.sub',true),'')::uuid
 AND g.enabled AND g.can_read AND CASE cap WHEN 'read' THEN true WHEN 'manage' THEN g.can_manage WHEN 'publish' THEN g.can_manage AND g.can_publish_catalog WHEN 'raw' THEN g.can_evidence AND g.can_amount ELSE false END)
$$;
CREATE FUNCTION catalog.new_item_authorize(s uuid,cap text) RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ BEGIN
 IF NOT coalesce(catalog.new_item_scope_allowed(s,cap),false) THEN RAISE EXCEPTION 'NEW_ITEM_DENIED' USING ERRCODE='42501'; END IF;
 RETURN nullif(current_setting('request.jwt.claim.sub',true),'')::uuid; END $$;
CREATE FUNCTION catalog.new_item_keys(p jsonb,allowed text[],required text[]) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path='' AS $$
 SELECT coalesce(jsonb_typeof(p)='object' AND NOT EXISTS(SELECT 1 FROM jsonb_object_keys(p) k WHERE NOT k=ANY(allowed)) AND p?&required,false) $$;
CREATE FUNCTION catalog.new_item_utc(t text) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
DECLARE v timestamptz; BEGIN
 IF t IS NULL THEN RETURN NULL; END IF;
 IF t!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$' THEN RAISE EXCEPTION 'PRODUCT_CAPTURE_ENVELOPE_INVALID' USING ERRCODE='22023'; END IF;
 BEGIN v:=t::timestamptz; EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'PRODUCT_CAPTURE_ENVELOPE_INVALID' USING ERRCODE='22023'; END;
 IF to_char(v AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')<>t THEN RAISE EXCEPTION 'PRODUCT_CAPTURE_ENVELOPE_INVALID' USING ERRCODE='22023'; END IF; RETURN t; END $$;
CREATE FUNCTION catalog.new_item_envelope(p jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
BEGIN
 IF p IS NULL OR jsonb_typeof(p)<>'object' OR p->>'sourceAvailability' IS NULL OR p->>'documentAvailability' IS NULL
 OR p->>'sourceAvailability' NOT IN('known','not_observed') OR p->>'documentAvailability' NOT IN('known','not_observed')
 OR (p->>'sourceAvailability'='known') IS DISTINCT FROM (jsonb_typeof(p->'sourceEffectiveAt')='string')
 OR (p->>'documentAvailability'='known') IS DISTINCT FROM (jsonb_typeof(p->'documentModifiedAt')='string')
 OR (p->>'sourceAvailability'='not_observed' AND p->'sourceEffectiveAt' IS DISTINCT FROM 'null'::jsonb)
 OR (p->>'documentAvailability'='not_observed' AND p->'documentModifiedAt' IS DISTINCT FROM 'null'::jsonb)
 OR jsonb_typeof(p->'collectedAt') IS DISTINCT FROM 'string'
 THEN RAISE EXCEPTION 'PRODUCT_CAPTURE_ENVELOPE_INVALID' USING ERRCODE='22023'; END IF;
 PERFORM catalog.new_item_utc(p->>'sourceEffectiveAt'); PERFORM catalog.new_item_utc(p->>'documentModifiedAt'); PERFORM catalog.new_item_utc(p->>'collectedAt');
 RETURN jsonb_build_array('iceos-product-capture-v2',p->>'approvedFixtureId',p->>'fixtureManifestId',p->>'fixtureManifestSha256',p->>'scopeId',p->>'captureKey',p->>'bytesSha256',p->'sizeBytes',p->>'format',p->>'parserId',p->>'parserVersion',p->>'schemaVersion',p->'coverage',p->>'projectionSha256',p->'associationProofs',p->>'sourceAvailability',p->'sourceEffectiveAt',p->>'documentAvailability',p->'documentModifiedAt',p->>'collectedAt');
END $$;
CREATE FUNCTION catalog.new_item_safe_fields(p jsonb,ref text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
DECLARE k text;f jsonb;r jsonb:='{}';BEGIN FOR k,f IN SELECT * FROM jsonb_each(p) LOOP
 IF k='imageRef' THEN f:=jsonb_build_object('state','not_read','raw',NULL,'reason','IMAGE_NOT_PUBLISHED','evidenceRef',ref||'#'||k);
 ELSE f:=jsonb_set(f,'{evidenceRef}',to_jsonb(ref||'#'||k)); IF f->>'state' IN('parse_failed','not_read') THEN f:=jsonb_set(f,'{reason}',to_jsonb(CASE WHEN f->>'state'='parse_failed' THEN 'SOURCE_FIELD_PARSE_FAILED' WHEN f->>'reason'='FIELD_NOT_ADOPTED' THEN 'FIELD_NOT_ADOPTED' ELSE 'SOURCE_FIELD_NOT_READ' END)); ELSE f:=f-'reason'; END IF; END IF;
 r:=r||jsonb_build_object(k,f); END LOOP; RETURN r; END $$;
CREATE FUNCTION catalog.new_item_adopt(p jsonb,keys text[],ref text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
DECLARE k text;r jsonb:='{}';BEGIN
 IF keys IS NULL OR cardinality(keys)<>(SELECT count(DISTINCT x) FROM unnest(keys) x) OR EXISTS(SELECT 1 FROM unnest(keys) x WHERE x NOT IN('nameCn','englishName','specification','barcode','factory','packaging','cartonQuantity')) THEN RAISE EXCEPTION 'NEW_ITEM_INVALID_FIELDS' USING ERRCODE='22023'; END IF;
 FOREACH k IN ARRAY ARRAY['nameCn','englishName','specification','barcode','factory','packaging','cartonQuantity'] LOOP
 IF k=ANY(keys) THEN IF NOT coalesce(catalog.valid_field(p->k),false) THEN RAISE EXCEPTION 'NEW_ITEM_INVALID_FIELDS' USING ERRCODE='22023'; END IF; r:=r||jsonb_build_object(k,p->k);
 ELSE r:=r||jsonb_build_object(k,jsonb_build_object('state','not_read','raw',NULL,'reason','FIELD_NOT_ADOPTED','evidenceRef',ref||'#'||k)); END IF; END LOOP;
 r:=catalog.new_item_safe_fields(r,ref); RETURN r||jsonb_build_object('imageRef',jsonb_build_object('state','not_read','raw',NULL,'reason','IMAGE_NOT_PUBLISHED','evidenceRef',ref||'#imageRef')); END $$;
CREATE FUNCTION catalog.lock_source_disposition(p_record uuid) RETURNS void LANGUAGE sql SET search_path='' AS $$ SELECT pg_advisory_xact_lock(hashtextextended('catalog-source-target-v1:'||p_record::text,308)) $$;
CREATE FUNCTION catalog.intake_target_history(p_scope uuid,p_record uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ BEGIN
 PERFORM catalog.new_item_authorize(p_scope,'read');
 IF to_regclass('catalog.catalog_target_decision_revision') IS NOT NULL OR to_regclass('catalog.catalog_target_decision_current') IS NOT NULL OR to_regclass('catalog.target_decision_origin') IS NOT NULL OR to_regclass('catalog_private.target_decision_context') IS NOT NULL THEN RAISE EXCEPTION 'B_PROVIDER_REQUIRED' USING ERRCODE='23505'; END IF;
 RETURN '{"version":"intake-target-history-v1","bState":"not_installed","historyState":"unknown_not_installed","entries":[]}'::jsonb; END $$;
CREATE FUNCTION catalog.new_item_member_source(s uuid,iid uuid,p_fields jsonb,p_market jsonb,p_warehouse jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE i catalog.identity_observation;e catalog.identity_evidence;r catalog.source_record;cl catalog.identity_claim;ct catalog.source_identity_contract_revision;l catalog.observation_record_link;
BEGIN
 PERFORM catalog.new_item_authorize(s,'read');SELECT * INTO STRICT i FROM catalog.identity_observation WHERE id=iid AND scope_id=s;SELECT * INTO STRICT e FROM catalog.identity_evidence WHERE id=i.evidence_id AND scope_id=s;
 SELECT * INTO l FROM catalog.observation_record_link WHERE observation_key='identity:'||i.id::text ORDER BY link_revision DESC LIMIT 1;
 IF NOT FOUND THEN RETURN NULL; END IF;
 SELECT * INTO STRICT r FROM catalog.source_record WHERE id=l.record_id AND scope_id=s; SELECT * INTO STRICT cl FROM catalog.identity_claim WHERE id=r.active_claim_id;
 SELECT * INTO STRICT ct FROM catalog.source_identity_contract_revision WHERE contract_id=r.current_contract_id AND scope_id=s;
 IF NOT EXISTS(SELECT 1 FROM catalog.source_scope WHERE id=s AND scope_state='identity_ready')
 OR l.status<>'linked' OR r.state<>'active' OR l.contract_id<>r.current_contract_id OR cl.contract_id<>ct.contract_id
 OR catalog.identity_scope_context_status(s,p_market,p_warehouse)<>'compatible'
 OR catalog.identity_scope_context_status(s,i.market_context,i.warehouse_context)<>'compatible'
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(cl.original_key_fields) f WHERE i.fields->(f->>0)->>'value' IS DISTINCT FROM f->>1)
 OR(p_fields->'sku'->>'meaning'='value' AND p_fields->'sku'->>'raw' IS DISTINCT FROM i.fields->'sku'->>'value')
 OR(p_fields->'nameCn'->>'meaning'='value' AND p_fields->'nameCn'->>'raw' IS DISTINCT FROM i.fields->'name'->>'value')
 OR(p_fields->'barcode'->>'meaning'='value' AND i.fields->'barcode'->>'state'='value' AND p_fields->'barcode'->>'raw' IS DISTINCT FROM i.fields->'barcode'->>'value')
 THEN RAISE EXCEPTION 'SOURCE_DISPOSITION_CONFLICT' USING ERRCODE='23505'; END IF;
 RETURN jsonb_build_object('recordId',r.id,'revision',r.revision,'claimId',r.active_claim_id,'contractId',ct.contract_id,'contractRevision',ct.revision,'state',r.state,
 'identityObservationId',i.id,'identityEvidenceId',e.id,'identityRecordPointer',i.record_pointer,'identityBytesSha256',e.bytes_sha256,'identityPayloadSha256',i.payload_sha256,
 'identityLinkKey',l.observation_key,'identityLinkRevision',l.link_revision,'identityLinkProofId',l.proof_id);
END $$;
CREATE FUNCTION catalog.new_item_current_source(s uuid,oid uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE o catalog.product_observation;c catalog.product_capture;x record;v jsonb;result jsonb;rid uuid;found_rid uuid;source_proof jsonb;
BEGIN
 PERFORM catalog.new_item_authorize(s,'read');SELECT * INTO STRICT o FROM catalog.product_observation WHERE id=oid AND scope_id=s;SELECT * INTO STRICT c FROM catalog.product_capture WHERE id=o.capture_id;
 FOR x IN
 SELECT io.id, NULL::jsonb AS proof FROM catalog.identity_observation io JOIN catalog.identity_evidence ie ON ie.id=io.evidence_id WHERE io.id=o.identity_observation_id AND io.scope_id=s AND ie.bytes_sha256=c.bytes_sha256 AND io.record_pointer=o.record_pointer
 UNION ALL
 SELECT io.id,p.value FROM catalog.product_capture pc CROSS JOIN LATERAL jsonb_array_elements(pc.association_proofs) p(value)
 JOIN catalog.identity_observation io ON io.evidence_id=(p.value->'to'->>'evidenceId')::uuid AND io.record_pointer=p.value->'to'->>'recordPointer' AND io.scope_id=s
 JOIN catalog.identity_evidence ie ON ie.id=io.evidence_id
 WHERE pc.scope_id=s AND p.value->>'semantics'='same_source_record' AND p.value->'from'->>'captureKey'=c.capture_key AND p.value->'from'->>'recordPointer'=o.record_pointer
 AND p.value->'from'->>'bytesSha256'=c.bytes_sha256 AND p.value->'from'->>'payloadSha256'=o.payload_sha256 AND p.value->'to'->>'bytesSha256'=ie.bytes_sha256 AND p.value->'to'->>'payloadSha256'=io.payload_sha256
 LOOP
 v:=catalog.new_item_member_source(s,x.id,o.fields,o.market_context,o.warehouse_context);IF v IS NULL THEN CONTINUE;END IF;
 IF found_rid IS NOT NULL AND found_rid<>(v->>'recordId')::uuid THEN RAISE EXCEPTION 'SOURCE_DISPOSITION_CONFLICT' USING ERRCODE='23505';END IF;found_rid:=(v->>'recordId')::uuid;
 source_proof:=CASE WHEN x.proof IS NULL THEN jsonb_build_object('kind','direct_member') ELSE jsonb_build_object('kind','frozen_same_source','proof',x.proof) END;
 result:=v||jsonb_build_object('sourceProof',source_proof);
 END LOOP;
 SELECT source_record_id INTO rid FROM catalog.item_observation_origin WHERE observation_id=oid AND scope_id=s AND source_record_id IS NOT NULL LIMIT 1;
 IF rid IS NULL THEN rid:=o.source_record_id; END IF;
 IF rid IS NOT NULL AND (result IS NULL OR rid<>(result->>'recordId')::uuid) THEN RAISE EXCEPTION 'SOURCE_DISPOSITION_CONFLICT' USING ERRCODE='23505'; END IF;
 RETURN result;
END $$;
CREATE FUNCTION catalog.new_item_source_disposition(s uuid,rid uuid,oid uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE r jsonb;sl jsonb;os jsonb;fs jsonb;b jsonb;risk boolean;BEGIN
 PERFORM catalog.new_item_authorize(s,'read');
 IF rid IS NOT NULL THEN
 SELECT jsonb_build_object('sourceRecordId',source_record_id,'itemId',item_id,'creationDecisionId',creation_decision_id,'originId',origin_id) INTO sl FROM catalog.new_item_source_claim WHERE source_record_id=rid AND scope_id=s;
 SELECT coalesce(jsonb_agg(jsonb_build_object('originId',id,'itemId',item_id,'originKind',origin_kind) ORDER BY id),'[]') INTO os FROM catalog.item_observation_origin WHERE source_record_id=rid AND scope_id=s;
 WITH links AS MATERIALIZED(SELECT frozen_observation_id FROM catalog.observation_record_link WHERE record_id=rid AND scope_id=s AND frozen_observation_id IS NOT NULL),d AS MATERIALIZED(SELECT id,observation_id,selected_item_id,selected_jushuitan_ref,review_state FROM catalog.decision_evidence WHERE entry_kind='candidate_snapshot')
 SELECT coalesce(jsonb_agg(DISTINCT jsonb_build_object('decisionId',d.id,'itemId',d.selected_item_id,'jushuitanRef',d.selected_jushuitan_ref,'reviewState',d.review_state)),'[]') INTO fs FROM d JOIN links ON links.frozen_observation_id=d.observation_id;
 b:=catalog.intake_target_history(s,rid);
 ELSE os:='[]';fs:='[]';b:=catalog.intake_target_history(s,NULL);END IF;
 SELECT EXISTS(SELECT 1 FROM catalog.intake_classification_revision c WHERE c.scope_id=s AND(c.observation_id=oid OR c.source_record_id=rid OR EXISTS(SELECT 1 FROM catalog.item_observation_origin io WHERE io.observation_id=c.observation_id AND io.source_record_id=rid)) AND(c.classification='suspected_version' OR c.review_state='needs_review')) INTO risk;
 IF jsonb_typeof(b) IS DISTINCT FROM 'object' OR b->>'version' IS DISTINCT FROM 'intake-target-history-v1' OR b->>'bState' IS NULL OR b->>'bState' NOT IN('not_installed','installed') OR jsonb_typeof(b->'entries') IS DISTINCT FROM 'array'
 OR jsonb_typeof(b->'historyState') IS DISTINCT FROM 'string' OR b->>'historyState'=''
 THEN RAISE EXCEPTION 'B_PROVIDER_REQUIRED' USING ERRCODE='23505';END IF;
 -- Keep shape validation in a separate statement before any array function.
 IF(b->>'bState'='not_installed' AND(b->>'historyState' IS DISTINCT FROM 'unknown_not_installed' OR jsonb_array_length(b->'entries')<>0))
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(b->'entries') e WHERE jsonb_typeof(e) IS DISTINCT FROM 'object' OR NOT(e?'itemId' AND e?'status') OR e->>'status' IS NULL OR e->>'status' NOT IN('confirmed','needs_review','suspended','withdrawn','revoked') OR jsonb_typeof(e->'itemId') NOT IN('string','null') OR(jsonb_typeof(e->'itemId')='string' AND e->>'itemId'!~*'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'))
 THEN RAISE EXCEPTION 'B_PROVIDER_REQUIRED' USING ERRCODE='23505';END IF;
 r:=jsonb_build_object('version','source-disposition-v1','recordId',rid,'slot',sl,'origins',os,'frozenDecisions',fs,'b',b,'risk',risk);
 RETURN r||jsonb_build_object('sha256',catalog.identity_hash(catalog.identity_json(r)));END $$;
CREATE FUNCTION catalog.new_item_guard(d jsonb,target uuid,creating boolean) RETURNS void LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$ BEGIN
 IF d->>'risk'='true' THEN RAISE EXCEPTION 'NEW_ITEM_REVIEW_REQUIRED' USING ERRCODE='23505';END IF;
 IF creating AND(d->'slot'<>'null'::jsonb OR jsonb_array_length(d->'origins')>0 OR jsonb_array_length(d->'frozenDecisions')>0 OR jsonb_array_length(d->'b'->'entries')>0) THEN RAISE EXCEPTION 'SOURCE_ALREADY_CLAIMED' USING ERRCODE='23505';END IF;
 IF NOT creating AND(
 (d->'slot'<>'null'::jsonb AND(d->'slot'->>'itemId')::uuid IS DISTINCT FROM target)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(d->'origins') x WHERE(x->>'itemId')::uuid IS DISTINCT FROM target)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(d->'frozenDecisions') x WHERE(x->>'itemId')::uuid IS DISTINCT FROM target OR x->>'reviewState' IS DISTINCT FROM 'manual_selected')
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(d->'b'->'entries') x WHERE(x->>'itemId')::uuid IS DISTINCT FROM target OR x->>'status' IN('withdrawn','suspended','needs_review','revoked')))
 THEN RAISE EXCEPTION 'SOURCE_DISPOSITION_CONFLICT' USING ERRCODE='23505';END IF;END $$;

