CREATE FUNCTION catalog.new_item_confirmation_preview(s uuid,oid uuid,keys text[],code text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE o catalog.product_observation;c catalog.intake_classification_revision;src jsonb;snap jsonb;d jsonb;selected jsonb;sorted text[];safe jsonb;h text;BEGIN
 PERFORM catalog.new_item_authorize(s,'read');SELECT * INTO STRICT o FROM catalog.product_observation WHERE id=oid AND scope_id=s;SELECT * INTO c FROM catalog.intake_classification_revision WHERE observation_id=oid ORDER BY revision DESC LIMIT 1;
 src:=catalog.new_item_current_source(s,oid);snap:=CASE WHEN src IS NULL THEN NULL ELSE jsonb_build_object('recordId',src->>'recordId','revision',src->'revision','claimId',src->>'claimId') END;
 d:=catalog.new_item_source_disposition(s,(src->>'recordId')::uuid,oid);SELECT array_agg(x ORDER BY x COLLATE "C") INTO sorted FROM unnest(keys) x;
 safe:=catalog.new_item_safe_fields(o.fields,'scope-observation:'||oid::text);SELECT coalesce(jsonb_object_agg(k,safe->k),'{}') INTO selected FROM unnest(sorted) k;
 h:=catalog.identity_hash(catalog.identity_json(jsonb_build_array('iceos-new-item-preview-v1',s::text,oid::text,o.payload_sha256,c.revision,snap,d->>'sha256',to_jsonb(sorted),selected,code)));
 RETURN jsonb_build_object('previewId',h,'source',src,'sourceSnapshot',snap,'disposition',d,'classificationRevision',c.revision,'selectedFields',selected,'sortedKeys',to_jsonb(sorted));END $$;
CREATE FUNCTION catalog.new_item_slot_preview(s uuid,oid uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE o catalog.product_observation;c catalog.product_capture;cl catalog.intake_classification_revision;src jsonb;d jsonb;slot jsonb;cover jsonb;v integer;h text;cs jsonb;BEGIN
 IF NOT catalog.new_item_scope_allowed(s,'publish') THEN RETURN NULL;END IF;
 SELECT * INTO STRICT o FROM catalog.product_observation WHERE id=oid AND scope_id=s;SELECT * INTO STRICT c FROM catalog.product_capture WHERE id=o.capture_id;
 SELECT * INTO cl FROM catalog.intake_classification_revision WHERE observation_id=oid ORDER BY revision DESC LIMIT 1;
 src:=catalog.new_item_current_source(s,oid);IF src IS NULL THEN RETURN NULL;END IF;d:=catalog.new_item_source_disposition(s,(src->>'recordId')::uuid,oid);slot:=d->'slot';IF slot IS NULL OR slot='null'::jsonb THEN RETURN NULL;END IF;
 SELECT revision INTO STRICT v FROM catalog.item_current WHERE item_id=(slot->>'itemId')::uuid;
 cover:=jsonb_build_object('productObservationId',oid,'productCaptureId',c.id,'productBytesSha256',c.bytes_sha256,'productRecordPointer',o.record_pointer,'productPayloadSha256',o.payload_sha256,
 'identityObservationId',src->'identityObservationId','identityEvidenceId',src->'identityEvidenceId','identityRecordPointer',src->'identityRecordPointer','identityBytesSha256',src->'identityBytesSha256','identityPayloadSha256',src->'identityPayloadSha256',
 'recordId',src->'recordId','revision',src->'revision','claimId',src->'claimId','contractId',src->'contractId','contractRevision',src->'contractRevision','identityLinkKey',src->'identityLinkKey','identityLinkRevision',src->'identityLinkRevision',
 'proofPathDigest',catalog.identity_hash(catalog.identity_json(src->'sourceProof')));
 cs:=jsonb_build_object('revision',cl.revision,'classification',cl.classification,'reviewState',cl.review_state);
 h:=catalog.identity_hash(catalog.identity_json(jsonb_build_array('iceos-source-slot-preview-v1',s::text,oid::text,o.payload_sha256,cs,cover,slot,v,d->>'sha256')));
 RETURN jsonb_build_object('basisKind','source_slot','observationId',oid,'classificationRevision',cl.revision,'sourceCoverage',cover,'sourceDispositionSha256',d->>'sha256','slot',slot,'itemRevision',v,'previewId',h);END $$;
CREATE FUNCTION catalog.new_item_resolve_proof(s uuid,oid uuid,ref jsonb,sem text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE p jsonb;o catalog.product_observation;c catalog.product_capture;BEGIN
 IF NOT catalog.new_item_keys(ref,ARRAY['captureId','proofKey'],ARRAY['captureId','proofKey']) THEN RAISE EXCEPTION 'ASSOCIATION_PROOF_REQUIRED' USING ERRCODE='22023';END IF;
 SELECT * INTO STRICT o FROM catalog.product_observation WHERE id=oid AND scope_id=s;SELECT * INTO STRICT c FROM catalog.product_capture WHERE id=o.capture_id;
 SELECT x.value INTO p FROM catalog.product_capture pc CROSS JOIN LATERAL jsonb_array_elements(pc.association_proofs) x(value) WHERE pc.id=(ref->>'captureId')::uuid AND pc.scope_id=s AND x.value->>'proofKey'=ref->>'proofKey';
 IF p IS NULL OR p->>'semantics' IS DISTINCT FROM sem OR p->'from'->>'captureKey' IS DISTINCT FROM c.capture_key OR p->'from'->>'recordPointer' IS DISTINCT FROM o.record_pointer OR p->'from'->>'bytesSha256' IS DISTINCT FROM c.bytes_sha256 OR p->'from'->>'payloadSha256' IS DISTINCT FROM o.payload_sha256 THEN RAISE EXCEPTION 'ASSOCIATION_PROOF_INVALID' USING ERRCODE='22023';END IF;RETURN p;END $$;
CREATE FUNCTION catalog.new_item_read(p_scope uuid,p_observation uuid DEFAULT NULL,p_projection text DEFAULT 'safe') RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE result jsonb;obs jsonb:='[]';o catalog.product_observation;x jsonb;cl jsonb;hist jsonb;src jsonb;d jsonb;sp jsonb;origin jsonb;BEGIN
 PERFORM catalog.new_item_authorize(p_scope,CASE WHEN p_projection='sensitive_history' THEN 'raw' ELSE 'read' END);
 IF p_projection IS NULL OR p_projection NOT IN('safe','sensitive_history') THEN RAISE EXCEPTION 'NEW_ITEM_INVALID_INPUT' USING ERRCODE='22023';END IF;
 IF p_observation IS NOT NULL AND NOT EXISTS(SELECT 1 FROM catalog.product_observation WHERE id=p_observation AND scope_id=p_scope) THEN RAISE EXCEPTION 'NEW_ITEM_DENIED' USING ERRCODE='42501';END IF;
 IF p_projection='sensitive_history' THEN
 SELECT jsonb_build_object('projection',p_projection,'scopeId',p_scope,'observationId',p_observation,'events',coalesce(jsonb_agg(jsonb_build_object('requestId',request_id,'action',action,'observationId',observation_id,'itemId',item_id,'itemRevision',item_revision,'classificationRevision',classification_revision,'privateReason',reason,'associationProof',private_field_evidence->'associationProof','fieldEvidence',private_field_evidence-'associationProof','actorId',actor_id,'recordedAt',recorded_at) ORDER BY recorded_at,request_id),'[]')) INTO result FROM catalog.new_item_request WHERE scope_id=p_scope AND(p_observation IS NULL OR observation_id=p_observation);RETURN result;END IF;
 FOR o IN SELECT * FROM catalog.product_observation WHERE scope_id=p_scope AND(p_observation IS NULL OR id=p_observation) ORDER BY capture_id,record_pointer LOOP
 SELECT coalesce(jsonb_agg(jsonb_build_object('revision',revision,'classification',classification,'reviewState',review_state,'proposedItemId',proposed_item_id,'expectedItemRevision',expected_item_revision,'proposedFieldKeys',proposed_field_keys) ORDER BY revision),'[]') INTO hist FROM catalog.intake_classification_revision WHERE observation_id=o.id;
 cl:=CASE WHEN jsonb_array_length(hist)>0 THEN hist->(jsonb_array_length(hist)-1) ELSE NULL END;
 BEGIN src:=catalog.new_item_current_source(p_scope,o.id);d:=catalog.new_item_source_disposition(p_scope,(src->>'recordId')::uuid,o.id);sp:=catalog.new_item_slot_preview(p_scope,o.id);
 EXCEPTION WHEN SQLSTATE '23505' OR SQLSTATE '22023' THEN src:=NULL;sp:=NULL;d:=jsonb_build_object('sha256',catalog.identity_hash('blocked:'||o.id::text),'conflicts',jsonb_build_array('SOURCE_DISPOSITION_CONFLICT'));END;
 SELECT jsonb_build_object('originId',id,'observationId',observation_id,'itemId',item_id,'originKind',origin_kind,'associationBasisKind',association_basis_kind,'creationDecisionId',creation_decision_id,'sourceRecordId',source_record_id) INTO origin FROM catalog.item_observation_origin WHERE observation_id=o.id ORDER BY recorded_at,id LIMIT 1;
 obs:=obs||jsonb_build_array(jsonb_build_object('observationId',o.id,'captureId',o.capture_id,'recordPointer',o.record_pointer,'payloadSha256',o.payload_sha256,'fields',catalog.new_item_safe_fields(o.fields,'scope-observation:'||o.id::text),'position',o.position,'classification',cl,'classificationHistory',hist,'currentSource',CASE WHEN src IS NULL THEN NULL ELSE src-ARRAY['sourceProof','identityLinkProofId','identityBytesSha256','identityPayloadSha256','identityRecordPointer'] END,'sourceDisposition',d,'sourceSlotPreview',sp,'origin',origin));END LOOP;
 SELECT jsonb_build_object('scope',jsonb_build_object('scopeId',s.id,'displayName',s.display_name,'system',s.system,'scopeState',s.scope_state,'entityKind',s.entity_kind,'verificationEnvironment','fixture'),
 'permissions',jsonb_build_object('read',true,'manage',catalog.new_item_scope_allowed(p_scope,'manage'),'publish',catalog.new_item_scope_allowed(p_scope,'publish'),'evidence',catalog.identity_scope_allowed(p_scope,'evidence'),'amount',catalog.identity_scope_allowed(p_scope,'amount')),
 'captures',(SELECT coalesce(jsonb_agg(jsonb_build_object('captureId',id,'captureKey',capture_key,'approvedFixtureId',approved_fixture_id,'sha256',bytes_sha256,'size',size_bytes,'sourceEffectiveAt',CASE WHEN source_effective_at IS NULL THEN NULL ELSE to_char(source_effective_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END,'documentModifiedAt',CASE WHEN document_modified_at IS NULL THEN NULL ELSE to_char(document_modified_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END,'collectedAt',to_char(collected_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) ORDER BY id),'[]') FROM catalog.product_capture WHERE scope_id=p_scope),
 'observations',obs,'origins',(SELECT coalesce(jsonb_agg(jsonb_build_object('originId',id,'observationId',observation_id,'itemId',item_id,'originKind',origin_kind,'associationBasisKind',association_basis_kind,'creationDecisionId',creation_decision_id,'sourceRecordId',source_record_id) ORDER BY recorded_at,id),'[]') FROM catalog.item_observation_origin WHERE scope_id=p_scope)) INTO result FROM catalog.source_scope s WHERE id=p_scope;RETURN result;END $$;
CREATE FUNCTION catalog.new_item_mutate(p_request uuid,p_scope uuid,p_action text,p_intent text,p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid;prior catalog.new_item_request;pin jsonb;env jsonb;result jsonb;eid uuid;oid uuid;item uuid;did uuid;orig uuid;token uuid;ids uuid[]:='{}';x jsonb;f record;cp catalog.product_capture;o catalog.product_observation;cl catalog.intake_classification_revision;cv catalog.item_current;v catalog.item_revision;dec catalog.new_item_decision;oldorigin catalog.item_observation_origin;basisorigin catalog.item_observation_origin;slot catalog.new_item_source_claim;iid uuid;src jsonb;snap jsonb;d jsonb;ctx jsonb;sp jsonb;proof jsonb;basis jsonb;ev jsonb:='{}';fields jsonb;keys text[];code text;ref text;rev integer;classrev integer;reason text;business text;expected text;v_origin_kind text;basis_kind text:='none';baseline_release uuid;baseline_artifact uuid;baseline_pointer text;proof_capture uuid;proof_key text;source_id uuid;source_rev integer;source_claim uuid;coverage_obs uuid;coverage_key text;coverage_rev integer;slot_id uuid;request_observation uuid;request_class integer;request_item uuid;request_revision integer;adoptkeys text[]:='{}';was_existing boolean:=false;allowed text[];
BEGIN
 IF p_request IS NULL OR p_scope IS NULL OR p_action IS NULL OR p_action NOT IN('import_product_capture','classify_observation','confirm_new_item','associate_existing_item','attach_source_identity','assign_initial_code','append_nonprice_revision') OR p IS NULL OR jsonb_typeof(p)<>'object' OR p_intent IS NULL OR p_intent!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'NEW_ITEM_INVALID_INPUT' USING ERRCODE='22023';END IF;
 actor:=catalog.new_item_authorize(p_scope,CASE WHEN p_action IN('import_product_capture','classify_observation') THEN 'manage' ELSE 'publish' END);
 IF catalog.identity_hash(catalog.identity_json(jsonb_build_array('iceos-new-item-request-v1',actor::text,p_scope::text,p_action,p))) IS DISTINCT FROM p_intent THEN RAISE EXCEPTION 'REQUEST_CONFLICT' USING ERRCODE='23505';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_request::text,300));
 SELECT * INTO prior FROM catalog.new_item_request WHERE request_id=p_request;
 IF FOUND THEN IF prior.scope_id<>p_scope OR prior.actor_id<>actor OR prior.action<>p_action OR prior.intent_sha256<>p_intent THEN RAISE EXCEPTION 'REQUEST_CONFLICT' USING ERRCODE='23505';END IF;RETURN prior.result;END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_scope::text,301));
 IF p_action='import_product_capture' THEN
 allowed:=ARRAY['approvedFixtureId','fixtureManifestId','fixtureManifestSha256','scopeId','captureKey','bytesSha256','sizeBytes','format','parserId','parserVersion','schemaVersion','coverage','projectionSha256','associationProofs','sourceAvailability','sourceEffectiveAt','documentAvailability','documentModifiedAt','collectedAt','observations','adoptionDigest','storageHandle'];
 IF NOT catalog.new_item_keys(p,allowed,allowed) THEN RAISE EXCEPTION 'PRODUCT_CAPTURE_ENVELOPE_INVALID' USING ERRCODE='22023';END IF;
 env:=catalog.new_item_envelope(p);pin:=catalog.new_item_fixture_pin(p->>'approvedFixtureId');
 IF pin IS NULL OR p_scope::text IS DISTINCT FROM p->>'scopeId' OR p-'storageHandle' IS DISTINCT FROM pin OR catalog.identity_hash(catalog.identity_json(env)) IS DISTINCT FROM p->>'adoptionDigest'
 THEN RAISE EXCEPTION 'PRODUCT_CAPTURE_PIN_CONFLICT' USING ERRCODE='22023';END IF;
 IF p->>'storageHandle' IS DISTINCT FROM substr(p->>'bytesSha256',1,2)||'/'||(p->>'bytesSha256') OR catalog.identity_hash(catalog.identity_json(p->'observations')) IS DISTINCT FROM p->>'projectionSha256' THEN RAISE EXCEPTION 'PRODUCT_CAPTURE_PIN_CONFLICT' USING ERRCODE='22023';END IF;
 SELECT * INTO cp FROM catalog.product_capture WHERE scope_id=p_scope AND capture_key=p->>'captureKey';was_existing:=FOUND;
 IF was_existing THEN IF cp.adoption_digest<>p->>'adoptionDigest' THEN RAISE EXCEPTION 'PRODUCT_CAPTURE_PIN_CONFLICT' USING ERRCODE='22023';END IF;eid:=cp.id;SELECT coalesce(array_agg(id ORDER BY record_pointer),'{}') INTO ids FROM catalog.product_observation WHERE capture_id=eid;
 ELSE eid:=gen_random_uuid();
 INSERT INTO catalog.product_capture(id,scope_id,capture_key,approved_fixture_id,manifest_id,fixture_manifest_sha256,bytes_sha256,projection_sha256,size_bytes,format,parser_id,parser_version,schema_version,adoption_digest,association_proofs,coverage,source_effective_at,source_availability,document_modified_at,document_availability,collected_at,actor_id,request_id)
 VALUES(eid,p_scope,p->>'captureKey',p->>'approvedFixtureId',p->>'fixtureManifestId',p->>'fixtureManifestSha256',p->>'bytesSha256',p->>'projectionSha256',(p->>'sizeBytes')::bigint,p->>'format',p->>'parserId',p->>'parserVersion',p->>'schemaVersion',p->>'adoptionDigest',p->'associationProofs',p->'coverage',(p->>'sourceEffectiveAt')::timestamptz,p->>'sourceAvailability',(p->>'documentModifiedAt')::timestamptz,p->>'documentAvailability',(p->>'collectedAt')::timestamptz,actor,p_request);
 INSERT INTO catalog_private.product_capture_handle VALUES(eid,p_scope,p->>'storageHandle');
 FOR x IN SELECT * FROM jsonb_array_elements(p->'observations') LOOP
 IF catalog.identity_hash(catalog.identity_json(x-'payloadSha256')) IS DISTINCT FROM x->>'payloadSha256' OR NOT coalesce(catalog.identity_context_valid(x->'marketContext'),false) OR NOT coalesce(catalog.identity_context_valid(x->'warehouseContext'),false) THEN RAISE EXCEPTION 'PRODUCT_CAPTURE_ENVELOPE_INVALID' USING ERRCODE='22023';END IF;
 FOR f IN SELECT * FROM jsonb_each(x->'fields') LOOP IF f.key NOT IN('nameCn','englishName','specification','barcode','factory','packaging','cartonQuantity','imageRef','sku','vendorRecordId') OR NOT coalesce(catalog.valid_field(f.value),false) THEN RAISE EXCEPTION 'PRODUCT_CAPTURE_ENVELOPE_INVALID' USING ERRCODE='22023';END IF;END LOOP;
 -- Validate EVERY same-byte member before choosing the saved direct reference.
 -- Invalid or conflicting members cannot be hidden by selecting the first success.
 src:=NULL;
 FOR iid IN SELECT io.id FROM catalog.identity_observation io JOIN catalog.identity_evidence ie ON ie.id=io.evidence_id
 WHERE io.scope_id=p_scope AND ie.bytes_sha256=p->>'bytesSha256' AND io.record_pointer=x->>'recordPointer' ORDER BY io.id LOOP
 ctx:=catalog.new_item_member_source(p_scope,iid,x->'fields',x->'marketContext',x->'warehouseContext');
 IF ctx IS NOT NULL THEN IF src IS NOT NULL AND src->>'recordId' IS DISTINCT FROM ctx->>'recordId' THEN RAISE EXCEPTION 'SOURCE_DISPOSITION_CONFLICT' USING ERRCODE='23505';END IF;IF src IS NULL THEN src:=ctx;END IF;END IF;END LOOP;
 iid:=(src->>'identityObservationId')::uuid;
 oid:=gen_random_uuid();INSERT INTO catalog.product_observation(id,scope_id,capture_id,record_pointer,position,fields,market_context,warehouse_context,payload_sha256,raw_ref,identity_observation_id)
 VALUES(oid,p_scope,eid,x->>'recordPointer',x->'position',x->'fields',x->'marketContext',x->'warehouseContext',x->>'payloadSha256',x->>'rawRef',iid);PERFORM catalog.new_item_current_source(p_scope,oid);ids:=array_append(ids,oid);END LOOP;END IF;
 result:=jsonb_build_object('captureId',eid,'observationIds',to_jsonb(ids),'imported',NOT was_existing,'relationshipUsable',false);reason:='APPROVED_PRODUCT_CAPTURE';
 ELSE
 reason:=p->>'privateReason';IF reason IS NULL OR length(btrim(reason))=0 OR length(reason)>1000 THEN RAISE EXCEPTION 'NEW_ITEM_INVALID_INPUT' USING ERRCODE='22023';END IF;
 IF p_action IN('assign_initial_code','append_nonprice_revision') THEN
 allowed:=CASE WHEN p_action='assign_initial_code' THEN ARRAY['itemId','expectedRevision','code','privateReason'] ELSE ARRAY['itemId','expectedRevision','fields','privateReason'] END;
 IF NOT catalog.new_item_keys(p,allowed,allowed) OR (p->>'expectedRevision')::integer IS NULL OR (p->>'expectedRevision')::integer<=0 THEN RAISE EXCEPTION 'NEW_ITEM_INVALID_INPUT' USING ERRCODE='22023';END IF;
 item:=(p->>'itemId')::uuid;SELECT * INTO STRICT dec FROM catalog.new_item_decision WHERE item_id=item;
 IF dec.scope_id<>p_scope THEN RAISE EXCEPTION 'CROSS_SCOPE_ASSOCIATION_REQUIRED' USING ERRCODE='42501';END IF;
 IF p_action='append_nonprice_revision' THEN
 IF p->'fields'?'imageRef' THEN RAISE EXCEPTION 'IMAGE_PUBLICATION_NOT_IMPLEMENTED' USING ERRCODE='22023';END IF;
 IF jsonb_typeof(p->'fields') IS DISTINCT FROM 'object' OR p->'fields'='{}'::jsonb THEN RAISE EXCEPTION 'NEW_ITEM_INVALID_FIELDS' USING ERRCODE='22023';END IF;
 FOR f IN SELECT * FROM jsonb_each(p->'fields') LOOP IF f.key NOT IN('nameCn','englishName','specification','barcode','factory','packaging','cartonQuantity') OR NOT coalesce(catalog.valid_field(f.value),false) THEN RAISE EXCEPTION 'NEW_ITEM_INVALID_FIELDS' USING ERRCODE='22023';END IF;END LOOP;END IF;
 -- Known C item: resolve all its source locks before the item lock.
 FOR source_id IN SELECT DISTINCT source_record_id FROM catalog.item_observation_origin WHERE item_id=item AND source_record_id IS NOT NULL ORDER BY source_record_id LOOP PERFORM catalog.lock_source_disposition(source_id);END LOOP;
 PERFORM pg_advisory_xact_lock(hashtextextended('catalog-product-observation-v1:'||dec.observation_id::text,309));
 SELECT * INTO STRICT cv FROM catalog.item_current WHERE item_id=item FOR UPDATE;
 IF cv.revision<>(p->>'expectedRevision')::integer THEN RAISE EXCEPTION 'NEW_ITEM_REVISION_CONFLICT' USING ERRCODE='40001';END IF;
 SELECT * INTO STRICT v FROM catalog.item_revision WHERE item_id=item AND revision=cv.revision;rev:=cv.revision+1;token:=gen_random_uuid();ref:='catalog-pub:'||token::text;
 IF p_action='assign_initial_code' THEN code:=p->>'code';IF code IS NULL OR length(code)>50 OR code!~'[^[:space:]]' OR code~'^[[:space:]]|[[:space:]]$' THEN RAISE EXCEPTION 'NEW_ITEM_INVALID_INPUT' USING ERRCODE='22023';END IF;
 IF EXISTS(SELECT 1 FROM catalog.catalog_item_code WHERE item_id=item) THEN RAISE EXCEPTION 'CATALOG_CODE_IMMUTABLE' USING ERRCODE='23505';END IF;
 INSERT INTO catalog.catalog_item_code(item_id,ice_code,evidence_ref,request_id) VALUES(item,code,ref,NULL);fields:=v.fields;
 ELSE code:=v.ice_code_snapshot;fields:=v.fields||catalog.new_item_safe_fields(p->'fields',ref);END IF;
 IF fields->'nameCn'->>'state' IS DISTINCT FROM 'observed' OR fields->'nameCn'->>'meaning' IS DISTINCT FROM 'value' OR length(btrim(fields->'nameCn'->>'raw'))=0 THEN RAISE EXCEPTION 'CATALOG_NAME_REQUIRED' USING ERRCODE='22023';END IF;
 INSERT INTO catalog.item_revision(item_id,revision,previous_revision,ice_code_snapshot,name_cn,fields,evidence_ref,reason,actor_id) VALUES(item,rev,cv.revision,code,fields->'nameCn'->>'raw',fields,ref,CASE WHEN p_action='assign_initial_code' THEN 'INITIAL_CODE_ASSIGNED' ELSE 'NONPRICE_REVISED' END,actor);
 UPDATE catalog.item_current SET revision=rev WHERE item_id=item;
 ev:=jsonb_build_object('adoptedFieldEvidence',CASE WHEN p_action='append_nonprice_revision' THEN p->'fields' ELSE '{}'::jsonb END);request_item:=item;request_revision:=rev;request_observation:=dec.observation_id;
 result:=jsonb_build_object('itemId',item,'revision',rev,'iceCode',code,'relationshipUsable',false);
 ELSE
 allowed:=CASE p_action WHEN 'classify_observation' THEN ARRAY['observationId','expectedClassificationRevision','classification','reviewState','proposedItemId','expectedItemRevision','proposedFieldKeys','expectedSourceSnapshot','privateReason']
 WHEN 'confirm_new_item' THEN ARRAY['observationId','expectedClassificationRevision','expectedSourceSnapshot','expectedSourceDisposition','previewId','adoptedFieldKeys','initialCode','privateReason']
 WHEN 'associate_existing_item' THEN ARRAY['observationId','expectedClassificationRevision','expectedSourceDisposition','previewId','basis','privateReason']
 ELSE ARRAY['originId','observationId','itemId','expectedItemRevision','sourceRecordId','expectedRecordRevision','expectedClaimId','supportIdentityObservationId','expectedSourceDisposition','associationProofRef','privateReason'] END;
 IF NOT catalog.new_item_keys(p,allowed,allowed) THEN RAISE EXCEPTION 'NEW_ITEM_INVALID_INPUT' USING ERRCODE='22023';END IF;
 oid:=(p->>'observationId')::uuid;SELECT * INTO STRICT o FROM catalog.product_observation WHERE id=oid AND scope_id=p_scope;SELECT * INTO STRICT cp FROM catalog.product_capture WHERE id=o.capture_id;
 src:=catalog.new_item_current_source(p_scope,oid);source_id:=(src->>'recordId')::uuid;source_rev:=(src->>'revision')::integer;source_claim:=(src->>'claimId')::uuid;
 IF source_id IS NOT NULL THEN PERFORM catalog.lock_source_disposition(source_id);END IF;PERFORM pg_advisory_xact_lock(hashtextextended('catalog-product-observation-v1:'||oid::text,309));
 snap:=CASE WHEN src IS NULL THEN NULL ELSE jsonb_build_object('recordId',source_id,'revision',source_rev,'claimId',source_claim) END;
 d:=catalog.new_item_source_disposition(p_scope,source_id,oid);SELECT * INTO cl FROM catalog.intake_classification_revision WHERE observation_id=oid ORDER BY revision DESC LIMIT 1;classrev:=coalesce(cl.revision,0);
 request_observation:=oid;
 IF p_action='confirm_new_item' THEN
 SELECT * INTO dec FROM catalog.new_item_decision WHERE observation_id=oid;
 IF FOUND THEN SELECT * INTO STRICT prior FROM catalog.new_item_request WHERE request_id=dec.request_id;
 IF prior.private_field_evidence->'creationIntentSnapshot'->'payload' IS DISTINCT FROM p THEN RAISE EXCEPTION 'NEW_ITEM_INTENT_CONFLICT' USING ERRCODE='23505';END IF;
 result:=prior.result||jsonb_build_object('created',false);request_item:=dec.item_id;request_revision:=1;request_class:=dec.classification_revision;
 ELSE
 IF classrev IS DISTINCT FROM (p->>'expectedClassificationRevision')::integer OR classrev=0 OR cl.classification<>'new_item' OR cl.review_state<>'proposed' THEN RAISE EXCEPTION 'CLASSIFICATION_CONFLICT' USING ERRCODE='40001';END IF;
 IF p->'expectedSourceSnapshot' IS DISTINCT FROM coalesce(snap,'null'::jsonb) OR p->>'expectedSourceDisposition' IS DISTINCT FROM d->>'sha256' THEN RAISE EXCEPTION 'SOURCE_DISPOSITION_CONFLICT' USING ERRCODE='40001';END IF;
 SELECT array_agg(value ORDER BY value COLLATE "C") INTO keys FROM jsonb_array_elements_text(p->'adoptedFieldKeys');code:=p->>'initialCode';ctx:=catalog.new_item_confirmation_preview(p_scope,oid,keys,code);
 IF p->>'previewId' IS DISTINCT FROM ctx->>'previewId' THEN RAISE EXCEPTION 'SOURCE_DISPOSITION_CONFLICT' USING ERRCODE='40001';END IF;PERFORM catalog.new_item_guard(d,NULL,true);
 item:=gen_random_uuid();did:=gen_random_uuid();orig:=gen_random_uuid();token:=gen_random_uuid();ref:='catalog-pub:'||token::text;fields:=catalog.new_item_adopt(o.fields,keys,ref);
 IF fields->'nameCn'->>'state' IS DISTINCT FROM 'observed' OR fields->'nameCn'->>'meaning' IS DISTINCT FROM 'value' OR fields->'nameCn'->>'raw' IS NULL OR length(btrim(fields->'nameCn'->>'raw'))=0 THEN RAISE EXCEPTION 'CATALOG_NAME_REQUIRED' USING ERRCODE='22023';END IF;
 IF code IS NOT NULL AND(length(code)>50 OR code~'^[[:space:]]|[[:space:]]$' OR length(btrim(code))=0) THEN RAISE EXCEPTION 'NEW_ITEM_INVALID_INPUT' USING ERRCODE='22023';END IF;
 business:=catalog.identity_hash(catalog.identity_json(jsonb_build_array('iceos-new-item-business-v1',p_scope::text,oid::text,cp.id::text,o.payload_sha256,cp.parser_id,cp.parser_version,classrev,snap,src,p->>'expectedSourceDisposition',p->>'previewId',jsonb_build_object('keys',to_jsonb(keys),'fields',ctx->'selectedFields'),code,reason)));
 INSERT INTO catalog.new_item_decision(id,scope_id,observation_id,classification_revision,item_id,request_id,publication_token,adopted_field_keys,adoption_sha256,creation_business_sha256,actor_id) VALUES(did,p_scope,oid,classrev,item,p_request,token,keys,catalog.identity_hash(catalog.identity_json(fields)),business,actor);
 INSERT INTO catalog.catalog_item(id,first_release_id,new_product_confirmed,confirmation_ref,creation_decision_id) VALUES(item,NULL,true,ref,did);
 IF code IS NOT NULL THEN INSERT INTO catalog.catalog_item_code(item_id,ice_code,evidence_ref,request_id) VALUES(item,code,ref,NULL);END IF;
 INSERT INTO catalog.item_revision(item_id,revision,name_cn,ice_code_snapshot,fields,evidence_ref,reason,actor_id) VALUES(item,1,fields->'nameCn'->>'raw',code,fields,ref,'NEW_ITEM_CONFIRMED',actor);
 INSERT INTO catalog.item_current(item_id,revision,financial_revision) VALUES(item,1,NULL);
 INSERT INTO catalog.item_observation_origin(id,scope_id,observation_id,item_id,origin_kind,creation_decision_id,creation_observation_id,source_record_id,source_record_revision,source_claim_id,request_id,actor_id) VALUES(orig,p_scope,oid,item,'created',did,oid,source_id,source_rev,source_claim,p_request,actor);
 IF source_id IS NOT NULL THEN INSERT INTO catalog.new_item_source_claim(source_record_id,scope_id,creation_decision_id,item_id,origin_id,source_record_revision,source_claim_id,request_id,actor_id) VALUES(source_id,p_scope,did,item,orig,source_rev,source_claim,p_request,actor);END IF;
 request_item:=item;request_revision:=1;request_class:=classrev;adoptkeys:=keys;
 ev:=jsonb_build_object('creationIntentSnapshot',jsonb_build_object('payload',p,'context',ctx),'adoptedFieldEvidence',o.fields,'sourceDisposition',d);
 result:=jsonb_build_object('itemId',item,'creationDecisionId',did,'revision',1,'created',true,'codeState',CASE WHEN code IS NULL THEN 'awaiting_code' ELSE 'coded' END,'iceCode',code,'identityStatus',CASE WHEN source_id IS NULL THEN 'unknown' ELSE 'fixture_verified' END,'relationshipUsable',false);END IF;
 ELSIF p_action='associate_existing_item' AND p->'basis'='{"kind":"source_slot"}'::jsonb AND EXISTS(SELECT 1 FROM catalog.item_observation_origin io WHERE io.observation_id=oid AND io.scope_id=p_scope AND io.association_basis_kind='source_slot') THEN
 -- A different request may recover this immutable association, using its original
 -- business snapshot rather than a guard which now includes the association itself.
 SELECT * INTO STRICT oldorigin FROM catalog.item_observation_origin io WHERE io.observation_id=oid AND io.scope_id=p_scope AND io.association_basis_kind='source_slot';
 SELECT * INTO STRICT prior FROM catalog.new_item_request WHERE request_id=oldorigin.request_id;
 ev:=prior.private_field_evidence->'source_slot_basis';
 -- Current protected histories must be evaluated before historical intent matching.
 PERFORM catalog.new_item_guard(d,oldorigin.item_id,false);
 IF p IS DISTINCT FROM jsonb_build_object('observationId',oid,'expectedClassificationRevision',ev->'classification'->'revision','expectedSourceDisposition',ev->'guard'->>'sha256','previewId',ev->>'previewId','basis',jsonb_build_object('kind','source_slot'),'privateReason',prior.reason)
 OR classrev IS DISTINCT FROM (ev->'classification'->>'revision')::integer
 OR src IS NULL OR snap IS DISTINCT FROM ((ev->'source')-ARRAY['contractId','contractRevision'])
 OR src->>'contractId' IS DISTINCT FROM ev->'source'->>'contractId' OR src->'contractRevision' IS DISTINCT FROM ev->'source'->'contractRevision'
 OR src->>'identityObservationId' IS DISTINCT FROM ev->'identityMember'->>'observationId' OR src->>'identityLinkKey' IS DISTINCT FROM ev->'identityLink'->>'observationKey'
 OR src->'identityLinkRevision' IS DISTINCT FROM ev->'identityLink'->'revision' OR src->>'identityLinkProofId' IS DISTINCT FROM ev->'identityLink'->>'proofId'
 OR src->'sourceProof' IS DISTINCT FROM ev->'sourceProof'
 THEN RAISE EXCEPTION 'NEW_ITEM_INTENT_CONFLICT' USING ERRCODE='23505';END IF;
 -- Recomputed from the saved strict snapshot and reason; no second stored digest/key.
 business:=catalog.identity_hash(catalog.identity_json(jsonb_build_array('iceos-source-slot-association-v1',p_scope::text,oid::text,ev,reason)));
 IF business IS DISTINCT FROM catalog.identity_hash(catalog.identity_json(jsonb_build_array('iceos-source-slot-association-v1',p_scope::text,oid::text,ev,prior.reason))) THEN RAISE EXCEPTION 'NEW_ITEM_INTENT_CONFLICT' USING ERRCODE='23505';END IF;
 result:=prior.result;request_item:=prior.item_id;request_revision:=prior.item_revision;request_class:=prior.classification_revision;ev:='{}';
 ELSIF p_action='classify_observation' THEN
 IF classrev IS DISTINCT FROM (p->>'expectedClassificationRevision')::integer THEN RAISE EXCEPTION 'CLASSIFICATION_CONFLICT' USING ERRCODE='40001';END IF;
 IF p->>'classification' IS NULL OR p->>'classification' NOT IN('new_item','item_update','external_sku','suspected_version') OR p->>'reviewState' IS NULL OR p->>'reviewState' NOT IN('proposed','needs_review') OR p->'expectedSourceSnapshot' IS DISTINCT FROM coalesce(snap,'null'::jsonb) THEN RAISE EXCEPTION 'NEW_ITEM_INVALID_INPUT' USING ERRCODE='22023';END IF;
 IF p->>'classification'='item_update' AND p->>'proposedItemId' IS NULL THEN RAISE EXCEPTION 'NEW_ITEM_INVALID_INPUT' USING ERRCODE='22023';END IF;
 INSERT INTO catalog.intake_classification_revision(observation_id,scope_id,revision,previous_revision,classification,review_state,proposed_item_id,expected_item_revision,proposed_field_keys,source_record_id,source_record_revision,source_claim_id,reason,request_id,actor_id)
 VALUES(oid,p_scope,classrev+1,CASE WHEN classrev=0 THEN NULL ELSE classrev END,p->>'classification',p->>'reviewState',(p->>'proposedItemId')::uuid,(p->>'expectedItemRevision')::integer,ARRAY(SELECT jsonb_array_elements_text(p->'proposedFieldKeys')),source_id,source_rev,source_claim,reason,p_request,actor);
 request_class:=classrev+1;result:=jsonb_build_object('observationId',oid,'classificationRevision',classrev+1,'relationshipUsable',false);
 ELSE
 -- The remaining two actions append provenance, never a public revision.
 IF classrev=0 OR cl.review_state<>'proposed' OR cl.classification='suspected_version' THEN RAISE EXCEPTION 'NEW_ITEM_REVIEW_REQUIRED' USING ERRCODE='23505';END IF;
 IF p->>'expectedSourceDisposition' IS DISTINCT FROM d->>'sha256' THEN RAISE EXCEPTION 'SOURCE_DISPOSITION_CONFLICT' USING ERRCODE='40001';END IF;
 proof:=NULL;basis_kind:='none';v_origin_kind:=CASE WHEN p_action='associate_existing_item' THEN 'associated_existing' ELSE 'source_attached' END;
 IF p_action='associate_existing_item' THEN
 IF classrev IS DISTINCT FROM (p->>'expectedClassificationRevision')::integer THEN RAISE EXCEPTION 'CLASSIFICATION_CONFLICT' USING ERRCODE='40001';END IF;basis:=p->'basis';basis_kind:=basis->>'kind';
 IF basis_kind='source_slot' THEN
 IF NOT catalog.new_item_keys(basis,ARRAY['kind'],ARRAY['kind']) THEN RAISE EXCEPTION 'NEW_ITEM_INVALID_INPUT' USING ERRCODE='22023';END IF;
 sp:=catalog.new_item_slot_preview(p_scope,oid);IF sp IS NULL OR p->>'previewId' IS DISTINCT FROM sp->>'previewId' THEN RAISE EXCEPTION 'SOURCE_DISPOSITION_CONFLICT' USING ERRCODE='40001';END IF;
 SELECT * INTO STRICT slot FROM catalog.new_item_source_claim WHERE source_record_id=source_id AND scope_id=p_scope;item:=slot.item_id;did:=slot.creation_decision_id;slot_id:=slot.source_record_id;SELECT * INTO STRICT basisorigin FROM catalog.item_observation_origin WHERE id=slot.origin_id;
 SELECT * INTO STRICT dec FROM catalog.new_item_decision WHERE id=did;coverage_obs:=(src->>'identityObservationId')::uuid;coverage_key:=src->>'identityLinkKey';coverage_rev:=(src->>'identityLinkRevision')::integer;
 IF src->'sourceProof'->>'kind'='frozen_same_source' THEN proof:=src->'sourceProof'->'proof';SELECT pc.id INTO proof_capture FROM catalog.product_capture pc CROSS JOIN LATERAL jsonb_array_elements(pc.association_proofs) pp(value) WHERE pc.scope_id=p_scope AND pp.value=proof LIMIT 1;proof_key:=proof->>'proofKey';END IF;
 ev:=jsonb_build_object('source_slot_basis',jsonb_build_object('productMember',jsonb_build_object('observationId',oid,'captureId',cp.id,'captureKey',cp.capture_key,'recordPointer',o.record_pointer,'bytesSha256',cp.bytes_sha256,'payloadSha256',o.payload_sha256),
 'identityMember',jsonb_build_object('observationId',coverage_obs,'evidenceId',src->>'identityEvidenceId','recordPointer',src->>'identityRecordPointer','bytesSha256',src->>'identityBytesSha256','payloadSha256',src->>'identityPayloadSha256'),
 'source',snap||jsonb_build_object('contractId',src->>'contractId','contractRevision',src->'contractRevision'),'identityLink',jsonb_build_object('observationKey',coverage_key,'revision',coverage_rev,'status','linked','recordId',source_id,'contractId',src->>'contractId','proofId',src->>'identityLinkProofId'),
 'sourceProof',src->'sourceProof','slot',sp->'slot','creationObservationId',dec.observation_id,'itemRevision',sp->'itemRevision','classification',jsonb_build_object('revision',cl.revision,'classification',cl.classification,'reviewState',cl.review_state),'guard',d,'previewId',sp->>'previewId'));
 ELSE
 IF basis_kind IS DISTINCT FROM 'catalog_proof' OR NOT catalog.new_item_keys(basis,ARRAY['kind','basisAnchorOrOrigin','associationProofRef','targetItemId','expectedItemRevision'],ARRAY['kind','basisAnchorOrOrigin','associationProofRef','targetItemId','expectedItemRevision']) THEN RAISE EXCEPTION 'ASSOCIATION_PROOF_REQUIRED' USING ERRCODE='22023';END IF;
 proof:=catalog.new_item_resolve_proof(p_scope,oid,basis->'associationProofRef','same_catalog_item');proof_capture:=(basis->'associationProofRef'->>'captureId')::uuid;proof_key:=basis->'associationProofRef'->>'proofKey';
 IF proof->'to'->>'kind'='product_observation' THEN
 SELECT io.* INTO STRICT basisorigin FROM catalog.product_capture pc JOIN catalog.product_observation po ON po.capture_id=pc.id JOIN catalog.item_observation_origin io ON io.observation_id=po.id AND io.origin_kind IN('created','associated_existing')
 WHERE pc.scope_id=p_scope AND pc.capture_key=proof->'to'->>'captureKey' AND pc.bytes_sha256=proof->'to'->>'bytesSha256' AND po.record_pointer=proof->'to'->>'recordPointer' AND po.payload_sha256=proof->'to'->>'payloadSha256';
 IF basis->'basisAnchorOrOrigin'->>'kind' IS DISTINCT FROM 'origin' OR(basis->'basisAnchorOrOrigin'->>'originId')::uuid IS DISTINCT FROM basisorigin.id THEN RAISE EXCEPTION 'ASSOCIATION_PROOF_INVALID' USING ERRCODE='22023';END IF;item:=basisorigin.item_id;
 ELSIF proof->'to'->>'kind'='baseline_anchor' THEN
 baseline_release:=(proof->'to'->>'releaseId')::uuid;baseline_artifact:=(proof->'to'->>'artifactId')::uuid;baseline_pointer:=proof->'to'->>'jsonPointer';
 SELECT a.item_id INTO STRICT item FROM catalog.baseline_item_anchor a JOIN catalog.baseline_release br ON br.id=a.release_id WHERE a.release_id=baseline_release AND a.artifact_id=baseline_artifact AND a.json_pointer=baseline_pointer AND a.payload_sha256=proof->'to'->>'payloadSha256' AND br.bundle_sha256=proof->'to'->>'bundleSha256';
 IF basis->'basisAnchorOrOrigin' IS DISTINCT FROM jsonb_build_object('kind','baseline_anchor','releaseId',baseline_release,'artifactId',baseline_artifact,'jsonPointer',baseline_pointer) THEN RAISE EXCEPTION 'ASSOCIATION_PROOF_INVALID' USING ERRCODE='22023';END IF;
 ELSE RAISE EXCEPTION 'ASSOCIATION_PROOF_INVALID' USING ERRCODE='22023';END IF;
 IF item IS DISTINCT FROM(basis->>'targetItemId')::uuid OR p->>'previewId' IS DISTINCT FROM catalog.identity_hash(catalog.identity_json(jsonb_build_array('iceos-catalog-proof-preview-v1',p_scope::text,oid::text,classrev,d->>'sha256',basis))) THEN RAISE EXCEPTION 'SOURCE_DISPOSITION_CONFLICT' USING ERRCODE='40001';END IF;
 ev:=jsonb_build_object('associationProof',proof,'sourceDisposition',d);END IF;
 ELSE
 item:=(p->>'itemId')::uuid;SELECT * INTO STRICT basisorigin FROM catalog.item_observation_origin WHERE id=(p->>'originId')::uuid AND observation_id=oid AND item_id=item AND scope_id=p_scope;
 IF src IS NULL OR (p->>'sourceRecordId')::uuid IS DISTINCT FROM source_id OR(p->>'expectedRecordRevision')::integer IS DISTINCT FROM source_rev OR(p->>'expectedClaimId')::uuid IS DISTINCT FROM source_claim OR(p->>'supportIdentityObservationId')::uuid IS DISTINCT FROM(src->>'identityObservationId')::uuid THEN RAISE EXCEPTION 'SOURCE_DISPOSITION_CONFLICT' USING ERRCODE='40001';END IF;
 IF p->'associationProofRef'='null'::jsonb THEN IF o.identity_observation_id IS NULL OR o.identity_observation_id IS DISTINCT FROM(src->>'identityObservationId')::uuid OR src->'sourceProof'->>'kind'<>'direct_member' THEN RAISE EXCEPTION 'ASSOCIATION_PROOF_REQUIRED' USING ERRCODE='22023';END IF;
 ELSE proof:=catalog.new_item_resolve_proof(p_scope,oid,p->'associationProofRef','same_source_record');IF proof IS DISTINCT FROM src->'sourceProof'->'proof' THEN RAISE EXCEPTION 'ASSOCIATION_PROOF_INVALID' USING ERRCODE='22023';END IF;proof_capture:=(p->'associationProofRef'->>'captureId')::uuid;proof_key:=p->'associationProofRef'->>'proofKey';END IF;
 ev:=jsonb_build_object('associationProof',proof,'sourceDisposition',d,'directMemberEvidence',src);END IF;
 SELECT * INTO STRICT cv FROM catalog.item_current WHERE item_id=item FOR UPDATE;
 IF p_action='associate_existing_item' AND basis_kind='source_slot' THEN expected:=sp->>'itemRevision';ELSE expected:=CASE WHEN p_action='associate_existing_item' THEN basis->>'expectedItemRevision' ELSE p->>'expectedItemRevision' END;END IF;
 IF expected IS NULL OR cv.revision IS DISTINCT FROM expected::integer THEN RAISE EXCEPTION 'NEW_ITEM_REVISION_CONFLICT' USING ERRCODE='40001';END IF;
 IF cl.proposed_item_id IS NOT NULL AND cl.proposed_item_id<>item THEN RAISE EXCEPTION 'SOURCE_DISPOSITION_CONFLICT' USING ERRCODE='23505';END IF;
 SELECT * INTO dec FROM catalog.new_item_decision WHERE item_id=item;IF FOUND AND dec.scope_id<>p_scope THEN RAISE EXCEPTION 'CROSS_SCOPE_ASSOCIATION_REQUIRED' USING ERRCODE='42501';END IF;did:=dec.id;
 PERFORM catalog.new_item_guard(d,item,false);
 SELECT * INTO oldorigin FROM catalog.item_observation_origin WHERE observation_id=oid AND catalog.item_observation_origin.origin_kind=v_origin_kind AND(v_origin_kind<>'source_attached' OR source_record_id=source_id) ORDER BY recorded_at LIMIT 1;
 IF FOUND THEN SELECT * INTO STRICT prior FROM catalog.new_item_request WHERE request_id=oldorigin.request_id;
 IF prior.reason<>reason OR oldorigin.item_id<>item OR prior.action<>p_action OR prior.private_field_evidence IS DISTINCT FROM ev THEN RAISE EXCEPTION 'NEW_ITEM_INTENT_CONFLICT' USING ERRCODE='23505';END IF;orig:=oldorigin.id;
 ELSE orig:=gen_random_uuid();
 INSERT INTO catalog.item_observation_origin(id,scope_id,observation_id,item_id,origin_kind,association_basis_kind,creation_decision_id,creation_observation_id,basis_origin_id,basis_source_slot_record_id,baseline_release_id,baseline_artifact_id,baseline_json_pointer,association_capture_id,association_proof_key,coverage_identity_observation_id,coverage_identity_link_key,coverage_identity_link_revision,source_record_id,source_record_revision,source_claim_id,request_id,actor_id)
 VALUES(orig,p_scope,oid,item,v_origin_kind,basis_kind,did,dec.observation_id,basisorigin.id,slot_id,baseline_release,baseline_artifact,baseline_pointer,proof_capture,proof_key,coverage_obs,coverage_key,coverage_rev,source_id,source_rev,source_claim,p_request,actor);
 IF source_id IS NOT NULL AND did IS NOT NULL AND basis_kind<>'source_slot' AND NOT EXISTS(SELECT 1 FROM catalog.new_item_source_claim WHERE source_record_id=source_id) THEN INSERT INTO catalog.new_item_source_claim(source_record_id,scope_id,creation_decision_id,item_id,origin_id,source_record_revision,source_claim_id,request_id,actor_id) VALUES(source_id,p_scope,did,item,orig,source_rev,source_claim,p_request,actor);END IF;END IF;
 request_item:=item;request_revision:=cv.revision;request_class:=classrev;result:=jsonb_build_object('itemId',item,'revision',cv.revision,'created',false,'associated',true,'originId',orig,'relationshipUsable',false);
 END IF;
 END IF;
 END IF;
 INSERT INTO catalog.new_item_request(request_id,scope_id,actor_id,action,intent_sha256,result,reason,observation_id,classification_revision,item_id,item_revision,publication_token,adopted_field_keys,private_field_evidence,source_disposition_sha256)
 VALUES(p_request,p_scope,actor,p_action,p_intent,result,reason,request_observation,request_class,request_item,request_revision,token,adoptkeys,ev,d->>'sha256');
 RETURN result;
END $$;
CREATE FUNCTION catalog.new_item_receipt(p_request uuid,p_scope uuid,p_action text,p_intent text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE a uuid;q catalog.new_item_request;BEGIN
 IF p_request IS NULL OR p_scope IS NULL OR p_action IS NULL OR p_action NOT IN('import_product_capture','classify_observation','confirm_new_item','associate_existing_item','attach_source_identity','assign_initial_code','append_nonprice_revision') OR p_intent IS NULL OR p_intent!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'NEW_ITEM_INVALID_INPUT' USING ERRCODE='22023';END IF;
 a:=catalog.new_item_authorize(p_scope,CASE WHEN p_action IN('import_product_capture','classify_observation') THEN 'manage' ELSE 'publish' END);SELECT * INTO q FROM catalog.new_item_request WHERE request_id=p_request;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF q.actor_id<>a OR q.scope_id<>p_scope OR q.action<>p_action OR q.intent_sha256<>p_intent THEN RAISE EXCEPTION 'REQUEST_CONFLICT' USING ERRCODE='23505';END IF;RETURN q.result;END $$;
CREATE FUNCTION catalog.new_item_read_evidence(p_evidence uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE c catalog.product_capture;h text;BEGIN
 SELECT * INTO c FROM catalog.product_capture WHERE id=p_evidence;IF NOT FOUND THEN RAISE EXCEPTION 'NEW_ITEM_DENIED' USING ERRCODE='42501';END IF;
 PERFORM catalog.new_item_authorize(c.scope_id,'raw');SELECT storage_handle INTO STRICT h FROM catalog_private.product_capture_handle WHERE capture_id=c.id;
 RETURN jsonb_build_object('evidenceId',c.id,'scopeId',c.scope_id,'sha256',c.bytes_sha256,'size',c.size_bytes,'format',c.format,'storageHandle',h);END $$;
CREATE FUNCTION catalog.new_item_evidence_export(p_evidence uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE c catalog.product_capture;w jsonb;BEGIN SELECT * INTO c FROM catalog.product_capture WHERE id=p_evidence;IF NOT FOUND THEN RAISE EXCEPTION 'NEW_ITEM_DENIED' USING ERRCODE='42501';END IF;
 PERFORM catalog.new_item_authorize(c.scope_id,'read');w:=catalog.new_item_read(c.scope_id,NULL,'safe');
 RETURN jsonb_build_object('evidence',(SELECT value FROM jsonb_array_elements(w->'captures') WHERE value->>'captureId'=c.id::text),'observations',(SELECT coalesce(jsonb_agg(jsonb_set(value,'{sourceSlotPreview}','null'::jsonb)),'[]') FROM jsonb_array_elements(w->'observations') WHERE value->>'captureId'=c.id::text),'relationshipUsable',false);END $$;
CREATE FUNCTION catalog.new_item_fixture_bootstrap(p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE s jsonb;g jsonb;BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND rolsuper) OR p->>'fixtureMode' IS DISTINCT FROM 'fixture' THEN RAISE EXCEPTION 'NEW_ITEM_BOOTSTRAP_DENIED' USING ERRCODE='42501';END IF;
 FOR s IN SELECT * FROM jsonb_array_elements(p->'scopes') LOOP FOR g IN SELECT * FROM jsonb_array_elements(s->'grants') LOOP
 UPDATE catalog.source_scope_grant SET can_publish_catalog=coalesce((g->>'publish')::boolean,false) WHERE scope_id=(s->>'scopeId')::uuid AND profile_id=(g->>'profileId')::uuid;
 END LOOP;END LOOP;RETURN jsonb_build_object('fixtureMode','fixture','grantsConfigured',true);END $$;
CREATE FUNCTION catalog.new_item_publication_guard() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE v catalog.item_revision;c catalog.item_current;BEGIN
 IF NEW.publication_token IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO STRICT v FROM catalog.item_revision WHERE item_id=NEW.item_id AND revision=NEW.item_revision;SELECT * INTO STRICT c FROM catalog.item_current WHERE item_id=NEW.item_id;
 IF NEW.request_xid<>txid_current() OR c.revision<NEW.item_revision OR c.financial_revision IS NOT NULL OR v.actor_id<>NEW.actor_id OR v.evidence_ref<>'catalog-pub:'||NEW.publication_token::text OR v.reason NOT IN('NEW_ITEM_CONFIRMED','INITIAL_CODE_ASSIGNED','NONPRICE_REVISED')
 THEN RAISE EXCEPTION 'NEW_ITEM_PUBLICATION_MISMATCH' USING ERRCODE='23514';END IF;
 RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER new_item_publication_fact AFTER INSERT ON catalog.new_item_request DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION catalog.new_item_publication_guard();
DO $$ DECLARE t text;BEGIN
 FOREACH t IN ARRAY ARRAY['product_capture','product_observation','intake_classification_revision','new_item_decision','item_observation_origin','new_item_source_claim','new_item_request'] LOOP
 EXECUTE format('CREATE TRIGGER new_item_immutable BEFORE UPDATE OR DELETE ON catalog.%I FOR EACH ROW EXECUTE FUNCTION catalog.reject_history_mutation()',t);
 EXECUTE format('ALTER TABLE catalog.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE catalog.%I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY new_item_read_policy ON catalog.%I FOR SELECT USING(catalog.new_item_scope_allowed(scope_id,''read''))',t);
 EXECUTE format('CREATE POLICY new_item_write_policy ON catalog.%I FOR ALL USING(catalog.new_item_scope_allowed(scope_id,''manage'')) WITH CHECK(catalog.new_item_scope_allowed(scope_id,''manage''))',t);
 EXECUTE format('REVOKE ALL ON catalog.%I FROM PUBLIC,ice_p0_02_app_runner,ice_p0_02_auth_runner,ice_p0_02_sync_runner',t);
 END LOOP;
END $$;
CREATE TRIGGER new_item_handle_immutable BEFORE UPDATE OR DELETE ON catalog_private.product_capture_handle FOR EACH ROW EXECUTE FUNCTION catalog.reject_history_mutation();
ALTER TABLE catalog_private.product_capture_handle ENABLE ROW LEVEL SECURITY;ALTER TABLE catalog_private.product_capture_handle FORCE ROW LEVEL SECURITY;
CREATE POLICY new_item_handle_read ON catalog_private.product_capture_handle FOR SELECT USING(catalog.new_item_scope_allowed(scope_id,'raw'));
CREATE POLICY new_item_handle_write ON catalog_private.product_capture_handle FOR INSERT WITH CHECK(catalog.new_item_scope_allowed(scope_id,'manage'));
REVOKE ALL ON catalog_private.product_capture_handle FROM PUBLIC,ice_p0_02_app_runner,ice_p0_02_auth_runner,ice_p0_02_sync_runner;
REVOKE SELECT ON catalog.catalog_item FROM ice_p0_02_app_runner;
GRANT SELECT(id,first_release_id,new_product_confirmed,confirmation_ref,recorded_at) ON catalog.catalog_item TO ice_p0_02_app_runner;

CREATE OR REPLACE FUNCTION catalog.assign_initial_code(p_request uuid,p_intent text,p_item uuid,p_expected integer,p_code text,p_reason text,p_evidence text) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid; prior jsonb; c catalog.item_current; v catalog.item_revision; result jsonb;
BEGIN
 actor:=catalog.require_admin(); IF EXISTS(SELECT 1 FROM catalog.catalog_item i WHERE i.id=p_item AND i.creation_decision_id IS NOT NULL) THEN RAISE EXCEPTION 'NEW_ITEM_SCOPED_ACTION_REQUIRED' USING ERRCODE='42501'; END IF; prior:=catalog.existing_request(p_request,p_intent,'assign_initial_code'); IF prior IS NOT NULL THEN RETURN prior; END IF;
 IF p_item IS NULL OR p_expected IS NULL OR p_expected<=0 OR p_code IS NULL OR length(p_code)>50 OR length(btrim(p_code))=0 OR btrim(p_code)<>p_code
 OR p_code ~ '^[[:space:]]|[[:space:]]$' OR p_reason IS NULL OR length(btrim(p_reason))=0 OR length(p_reason)>1000
 OR p_evidence IS NULL OR length(btrim(p_evidence))=0 OR length(p_evidence)>500 THEN
  RAISE EXCEPTION 'CATALOG_INVALID_INPUT' USING ERRCODE='22023'; END IF;
 SELECT * INTO STRICT c FROM catalog.item_current WHERE item_id=p_item FOR UPDATE;
 IF c.revision<>p_expected THEN RAISE EXCEPTION 'CATALOG_REVISION_CONFLICT' USING ERRCODE='40001'; END IF;
 IF EXISTS(SELECT 1 FROM catalog.catalog_item_code WHERE item_id=p_item) THEN RAISE EXCEPTION 'CATALOG_CODE_IMMUTABLE' USING ERRCODE='23505'; END IF;
 SELECT * INTO STRICT v FROM catalog.item_revision WHERE item_id=p_item AND revision=c.revision;
 INSERT INTO catalog.catalog_item_code(item_id,ice_code,evidence_ref,request_id) VALUES(p_item,p_code,p_evidence,p_request);
 INSERT INTO catalog.item_revision(item_id,revision,previous_revision,ice_code_snapshot,name_cn,fields,evidence_ref,reason,actor_id)
 VALUES(p_item,c.revision+1,c.revision,p_code,v.name_cn,v.fields,p_evidence,p_reason,actor);
 UPDATE catalog.item_current SET revision=c.revision+1 WHERE item_id=p_item;
 result:=jsonb_build_object('itemId',p_item,'revision',c.revision+1,'iceCode',p_code);
 INSERT INTO catalog.audit_event(request_id,intent_sha256,actor_id,action,item_id,result) VALUES(p_request,p_intent,actor,'assign_initial_code',p_item,result);
 RETURN result;
END $$;

CREATE OR REPLACE FUNCTION catalog.append_nonprice_revision(p_request uuid,p_intent text,p_item uuid,p_expected integer,p_fields jsonb,p_reason text,p_evidence text) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid; prior jsonb; c catalog.item_current; v catalog.item_revision; result jsonb; e record; new_name text;
BEGIN
 actor:=catalog.require_admin(); IF EXISTS(SELECT 1 FROM catalog.catalog_item i WHERE i.id=p_item AND i.creation_decision_id IS NOT NULL) THEN RAISE EXCEPTION 'NEW_ITEM_SCOPED_ACTION_REQUIRED' USING ERRCODE='42501'; END IF; prior:=catalog.existing_request(p_request,p_intent,'append_nonprice_revision'); IF prior IS NOT NULL THEN RETURN prior; END IF;
 IF p_item IS NULL OR p_expected IS NULL OR p_expected<=0 OR p_fields IS NULL OR jsonb_typeof(p_fields)<>'object' OR p_fields='{}'::jsonb
 OR p_reason IS NULL OR length(btrim(p_reason))=0 OR length(p_reason)>1000 OR p_evidence IS NULL OR length(btrim(p_evidence))=0 OR length(p_evidence)>500
 THEN RAISE EXCEPTION 'CATALOG_INVALID_INPUT' USING ERRCODE='22023'; END IF;
 FOR e IN SELECT * FROM jsonb_each(p_fields) LOOP
  IF NOT e.key=ANY(ARRAY['nameCn','specification','factory','imageRef','barcode','packaging','cartonQuantity','englishName']) OR NOT coalesce(catalog.valid_field(e.value),false) THEN
   RAISE EXCEPTION 'CATALOG_INVALID_NONPRICE_FIELD' USING ERRCODE='22023'; END IF;
 END LOOP;
 SELECT * INTO STRICT c FROM catalog.item_current WHERE item_id=p_item FOR UPDATE;
 IF c.revision<>p_expected THEN RAISE EXCEPTION 'CATALOG_REVISION_CONFLICT' USING ERRCODE='40001'; END IF;
 SELECT * INTO STRICT v FROM catalog.item_revision WHERE item_id=p_item AND revision=c.revision;
 new_name:=CASE WHEN p_fields?'nameCn' THEN p_fields->'nameCn'->>'raw' ELSE v.name_cn END;
 IF new_name IS NULL OR length(new_name)=0 THEN RAISE EXCEPTION 'CATALOG_NAME_REQUIRED' USING ERRCODE='22023'; END IF;
 INSERT INTO catalog.item_revision(item_id,revision,previous_revision,ice_code_snapshot,name_cn,fields,evidence_ref,reason,actor_id)
 VALUES(p_item,c.revision+1,c.revision,v.ice_code_snapshot,new_name,v.fields||p_fields,p_evidence,p_reason,actor);
 UPDATE catalog.item_current SET revision=c.revision+1 WHERE item_id=p_item;
 result:=jsonb_build_object('itemId',p_item,'revision',c.revision+1,'iceCode',v.ice_code_snapshot);
 INSERT INTO catalog.audit_event(request_id,intent_sha256,actor_id,action,item_id,result) VALUES(p_request,p_intent,actor,'append_nonprice_revision',p_item,result);
 RETURN result;
END $$;

DO $$ DECLARE f record; BEGIN FOR f IN SELECT p.oid::regprocedure AS sig FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='catalog' AND (p.proname LIKE 'new_item_%' OR p.proname IN('lock_source_disposition','intake_target_history')) LOOP
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,ice_p0_02_app_runner,ice_p0_02_auth_runner,ice_p0_02_sync_runner',f.sig);END LOOP;END $$;
GRANT EXECUTE ON FUNCTION catalog.new_item_mutate(uuid,uuid,text,text,jsonb),catalog.new_item_receipt(uuid,uuid,text,text),catalog.new_item_read(uuid,uuid,text),catalog.new_item_evidence_export(uuid),catalog.new_item_read_evidence(uuid) TO ice_p0_02_app_runner;
GRANT EXECUTE ON FUNCTION catalog.new_item_fixture_bootstrap(jsonb) TO postgres;
RESET ROLE;
